/**
 * TASK: Complete the ChainEnd class below.
 *
 * The provided classes (do not change them) form a chain:
 *   - ChainA.toString() returns "A"
 *   - ChainB extends ChainA; its toString() returns super.toString() + ">B",
 *     so new ChainB().toString() is "A>B"
 *
 * ChainEnd extends ChainB. Override toString() in the same style, using
 * super.toString(), so that:
 *
 *   new ChainEnd().toString() -> "A>B>C"
 */
class ChainA {
    @Override
    public String toString() {
        return "A";
    }
}

class ChainB extends ChainA {
    @Override
    public String toString() {
        return super.toString() + ">B";
    }
}

public class ChainEnd extends ChainB {

    @Override
    public String toString() {
        // TODO: build on super.toString(), appending ">C"
        return "";
    }
}

