public class ChainEndTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("ChainA toString()", "A", new ChainA().toString());
        check("ChainB toString()", "A>B", new ChainB().toString());
        check("ChainEnd toString()", "A>B>C", new ChainEnd().toString());

        ChainA topRef = new ChainEnd();
        check("toString() through ChainA reference", "A>B>C", topRef.toString());
        check("string concatenation uses toString()", "value=A>B>C", "value=" + new ChainEnd());

        check("ChainEnd instanceof ChainB", true, new ChainEnd() instanceof ChainB);
        check("ChainEnd instanceof ChainA", true, new ChainEnd() instanceof ChainA);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

